def isPrime (n : Nat) : Bool := n >= 2 && (List.range (n - 1)).all (fun k => if k + 2 < n then n % (k + 2) != 0 else true)
def check_1021 : Bool := isPrime 1021 && 1020 = 2 ^ 2 * 3 * 5 * 17

