def trialPrime (p : Nat) : Bool := if p < 2 then false else decide (∀ d : Nat, 2 ≤ d → d * d ≤ p → p % d ≠ 0)
def fragmentCheck : Bool := trialPrime 0 = false && trialPrime 1 = false && trialPrime 2 = true && trialPrime 3 = true && trialPrime 4 = false && trialPrime 5 = true && trialPrime 6 = false && trialPrime 7 = true && trialPrime 9 = false
